class Gain { const int factor_; public: explicit Gain(int factor) : factor_(factor) {} int apply(int x) const { return factor_ * x; } };
int main() { Gain g{3}; std::cout << g.apply(4) << '\n'; }

#include <iostream>
#include <memory>
#include <vector>

class Guard { int& x_; int old_; public: explicit Guard(int& x) : x_(x), old_(x) { x_ = 9; } Guard(const Guard&) = delete; Guard& operator=(const Guard&) = delete; ~Guard() { x_ = old_; } };
int main() { int x = 4; { Guard g{x}; std::cout << x << ' '; } std::cout << x << '\n'; }

