#include <memory>
#include <vector>

class Setting { int value{}; public: Setting& set(int value) { this->value = value; return *this; } int get() const { return value; } };
int main() { Setting s; auto& same = s.set(2).set(8); std::cout << (&same == &s) << ' ' << s.get() << '\n'; }

#include <iostream>
#include <memory>
#include <vector>

class Range { int low_{0}, high_{10}; public: bool configure(int l,int h) { if (l > h) return false; low_=l; high_=h; return true; } bool contains(int x) const { return low_ <= x && x <= high_; } };
int main() { Range r; std::cout << r.configure(9,2) << ' ' << r.contains(5) << '\n'; }

#include <iostream>
#include <memory>
#include <vector>

struct Scale { int factor; int apply(int x) const { return factor*x; } };
class Meter { Scale scale_{3}; public: int read(int raw) const { return scale_.apply(raw); } };
int main() { Meter m; std::cout << m.read(7) << '\n'; }

