#include <iostream>
#include <memory>
#include <vector>

struct Filter { virtual bool accept(int x) const = 0; virtual ~Filter() = default; };
struct Positive : Filter { bool accept(int x) const override { return x > 0; } };
int select(int x,const Filter& f) { return f.accept(x) ? x : 0; }
int main() { Positive f; std::cout << select(-3,f) << ' ' << select(4,f) << '\n'; }

#include <iostream>
#include <memory>
#include <vector>

struct Offset { int value; int apply(int x) const { return x+value; } };
struct Limit { int high; int apply(int x) const { return x>high ? high : x; } };
class Pipeline { Offset offset_{2}; Limit limit_{10}; public: int run(int x) const { return limit_.apply(offset_.apply(x)); } };
int main() { Pipeline p; std::cout << p.run(4) << ' ' << p.run(20) << '\n'; }
